DROP TRIGGER role_grant_epoch;
DROP TRIGGER role_revoke_epoch;
DROP TRIGGER role_update_epoch;
CREATE TABLE capability_new(user_id TEXT NOT NULL REFERENCES member(user_id),name TEXT NOT NULL CHECK(name IN ('admin','moderator','verifier','reviewer:visual','reviewer:portability','reviewer:executable-source','publisher')),PRIMARY KEY(user_id,name));
INSERT INTO capability_new SELECT * FROM capability;
DROP TABLE capability;
ALTER TABLE capability_new RENAME TO capability;
CREATE TRIGGER role_grant_epoch AFTER INSERT ON capability BEGIN UPDATE authority_policy SET epoch=epoch+1 WHERE id=1; END;
CREATE TRIGGER role_revoke_epoch AFTER DELETE ON capability BEGIN UPDATE authority_policy SET epoch=epoch+1 WHERE id=1; END;
CREATE TRIGGER role_update_epoch AFTER UPDATE ON capability BEGIN UPDATE authority_policy SET epoch=epoch+1 WHERE id=1; END;
CREATE TABLE member_restriction(user_id TEXT PRIMARY KEY REFERENCES member(user_id),reason TEXT NOT NULL,restricted_at INTEGER NOT NULL,revision TEXT NOT NULL);
INSERT INTO member_restriction SELECT user_id,'Account restricted',created_at,'legacy:'||user_id FROM member WHERE status='suspended';
CREATE TABLE model_report(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES asset_version(id),reporter_id TEXT NOT NULL REFERENCES member(user_id),category TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','dismiss','withdraw')),created_at INTEGER NOT NULL,resolution_reason TEXT,resolved_by TEXT REFERENCES member(user_id),UNIQUE(version_id,reporter_id));
CREATE INDEX report_queue ON model_report(created_at);
CREATE INDEX report_member ON model_report(reporter_id,created_at);
CREATE TABLE member_appeal(id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES member(user_id),restriction_revision TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','uphold','reinstate')),created_at INTEGER NOT NULL,decision_reason TEXT,resolved_by TEXT REFERENCES member(user_id),UNIQUE(member_id,restriction_revision));
CREATE INDEX appeal_queue ON member_appeal(created_at);
CREATE TABLE address_block(id TEXT PRIMARY KEY,address_hash TEXT NOT NULL UNIQUE,reason TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX block_expiry ON address_block(expires_at);
CREATE TABLE mail_reservation(id TEXT PRIMARY KEY,day TEXT NOT NULL,month TEXT NOT NULL);
CREATE INDEX mail_day ON mail_reservation(day);
CREATE INDEX mail_month ON mail_reservation(month);
CREATE TRIGGER mail_admission BEFORE INSERT ON mail_reservation WHEN (SELECT count(*) FROM mail_reservation WHERE day=NEW.day)>=90 OR (SELECT count(*) FROM mail_reservation WHERE month=NEW.month)>=2700 BEGIN SELECT RAISE(ABORT,'mail_budget_exhausted'); END;
CREATE TABLE storage_reservation(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES member(user_id),kind TEXT NOT NULL CHECK(kind IN ('source','evidence','processing')),bytes INTEGER NOT NULL CHECK(bytes>=0));
INSERT INTO storage_reservation SELECT 'source:'||v.id,v.contributor_id,'source',sum(a.bytes) FROM asset_version v JOIN version_artifact a ON a.version_id=v.id GROUP BY v.id;
INSERT INTO storage_reservation SELECT 'evidence:'||owner_id||':'||sha256,owner_id,'evidence',bytes FROM review_attachment;
INSERT INTO storage_reservation SELECT 'processing:'||a.attempt_id||':'||a.path,p.owner_id,'processing',a.bytes FROM processing_artifact a JOIN processing_attempt t ON t.id=a.attempt_id JOIN processor p ON p.id=t.processor_id;
CREATE INDEX storage_owner ON storage_reservation(kind,owner_id);
CREATE TRIGGER storage_admission BEFORE INSERT ON storage_reservation WHEN NOT EXISTS(SELECT 1 FROM storage_reservation WHERE id=NEW.id) AND ((NEW.kind='source' AND ((SELECT COALESCE(sum(bytes),0) FROM storage_reservation WHERE kind='source')+NEW.bytes>536870912 OR (SELECT COALESCE(sum(bytes),0) FROM storage_reservation WHERE kind='source' AND owner_id=NEW.owner_id)+NEW.bytes>67108864)) OR (NEW.kind='evidence' AND ((SELECT COALESCE(sum(bytes),0) FROM storage_reservation WHERE kind='evidence')+NEW.bytes>134217728 OR (SELECT COALESCE(sum(bytes),0) FROM storage_reservation WHERE kind='evidence' AND owner_id=NEW.owner_id)+NEW.bytes>33554432 OR (SELECT count(*) FROM storage_reservation WHERE kind='evidence' AND owner_id=NEW.owner_id)>=32)) OR (NEW.kind='processing' AND (SELECT COALESCE(sum(bytes),0) FROM storage_reservation WHERE kind='processing')+NEW.bytes>134217728)) BEGIN SELECT RAISE(ABORT,'storage_budget_exhausted'); END;
CREATE TRIGGER submission_admission BEFORE INSERT ON asset_version WHEN NOT EXISTS(SELECT 1 FROM asset_version WHERE id=NEW.id) AND ((SELECT count(*) FROM asset_version WHERE state NOT IN ('published','withdrawn','rejected'))>=100 OR (SELECT count(*) FROM asset_version WHERE contributor_id=NEW.contributor_id AND state NOT IN ('published','withdrawn','rejected'))>=10) BEGIN SELECT RAISE(ABORT,'submission_budget_exhausted'); END;
CREATE TRIGGER token_admission BEFORE INSERT ON agent_token WHEN (SELECT count(*) FROM agent_token WHERE user_id=NEW.user_id AND revoked_at IS NULL AND expires_at>unixepoch()*1000)>=10 BEGIN SELECT RAISE(ABORT,'token_budget_exhausted'); END;
CREATE TRIGGER job_admission BEFORE INSERT ON processing_job WHEN NOT EXISTS(SELECT 1 FROM processing_job WHERE version_id=NEW.version_id) AND (SELECT count(*) FROM processing_job WHERE created_at>=unixepoch('now','start of day')*1000)>=100 BEGIN SELECT RAISE(ABORT,'job_budget_exhausted'); END;
CREATE TRIGGER report_admission BEFORE INSERT ON model_report WHEN NOT EXISTS(SELECT 1 FROM model_report WHERE version_id=NEW.version_id AND reporter_id=NEW.reporter_id) AND (SELECT count(*) FROM model_report WHERE reporter_id=NEW.reporter_id AND created_at>NEW.created_at-86400000)>=10 BEGIN SELECT RAISE(ABORT,'report_budget_exhausted'); END;
CREATE TRIGGER role_loss_publication AFTER DELETE ON capability BEGIN UPDATE asset_version SET state='withdrawn' WHERE state IN ('approved','published') AND ((approved_by=OLD.user_id AND OLD.name='publisher') OR (OLD.name='verifier' AND id IN (SELECT version_id FROM technical_attestation WHERE reviewer_id=OLD.user_id)) OR id IN (SELECT version_id FROM review_record WHERE reviewer_id=OLD.user_id AND 'reviewer:'||category=OLD.name)); END;
CREATE TRIGGER role_change_publication AFTER UPDATE ON capability WHEN OLD.user_id!=NEW.user_id OR OLD.name!=NEW.name BEGIN UPDATE asset_version SET state='withdrawn' WHERE state IN ('approved','published') AND ((approved_by=OLD.user_id AND OLD.name='publisher') OR (OLD.name='verifier' AND id IN (SELECT version_id FROM technical_attestation WHERE reviewer_id=OLD.user_id)) OR id IN (SELECT version_id FROM review_record WHERE reviewer_id=OLD.user_id AND 'reviewer:'||category=OLD.name)); END;
CREATE TRIGGER status_loss_publication AFTER UPDATE OF status ON member WHEN NEW.status!='active' BEGIN UPDATE asset_version SET state='withdrawn' WHERE state IN ('approved','published') AND (contributor_id=NEW.user_id OR approved_by=NEW.user_id OR id IN (SELECT version_id FROM review_record WHERE reviewer_id=NEW.user_id UNION SELECT version_id FROM technical_attestation WHERE reviewer_id=NEW.user_id UNION SELECT j.version_id FROM processing_job j JOIN processing_attempt a ON a.id=j.current_attempt JOIN processor p ON p.id=a.processor_id WHERE p.owner_id=NEW.user_id)); UPDATE agent_token SET revoked_at=unixepoch()*1000 WHERE user_id=NEW.user_id AND revoked_at IS NULL; END;
CREATE TRIGGER verification_loss_publication AFTER UPDATE OF emailVerified ON user WHEN NEW.emailVerified!=1 BEGIN UPDATE asset_version SET state='withdrawn' WHERE state IN ('approved','published') AND (contributor_id=NEW.id OR approved_by=NEW.id OR id IN (SELECT version_id FROM review_record WHERE reviewer_id=NEW.id UNION SELECT version_id FROM technical_attestation WHERE reviewer_id=NEW.id UNION SELECT j.version_id FROM processing_job j JOIN processing_attempt a ON a.id=j.current_attempt JOIN processor p ON p.id=a.processor_id WHERE p.owner_id=NEW.id)); UPDATE agent_token SET revoked_at=unixepoch()*1000 WHERE user_id=NEW.id AND revoked_at IS NULL; END;
CREATE TRIGGER processor_loss_publication AFTER UPDATE ON processor BEGIN UPDATE asset_version SET state='withdrawn' WHERE state IN ('approved','published') AND id IN (SELECT j.version_id FROM processing_job j JOIN processing_attempt a ON a.id=j.current_attempt WHERE a.processor_id=OLD.id); END;
CREATE TRIGGER profile_loss_publication AFTER UPDATE ON processing_profile BEGIN UPDATE asset_version SET state='withdrawn' WHERE state IN ('approved','published') AND id IN (SELECT j.version_id FROM processing_job j JOIN processing_attempt a ON a.id=j.current_attempt WHERE a.profile_id=OLD.id); END;
CREATE TRIGGER version_current_member BEFORE INSERT ON asset_version WHEN NOT EXISTS(SELECT 1 FROM member m JOIN user u ON u.id=m.user_id WHERE m.user_id=NEW.contributor_id AND m.status='active' AND u.emailVerified=1) BEGIN SELECT RAISE(ABORT,'authority_changed'); END;
CREATE TRIGGER token_current_member BEFORE INSERT ON agent_token WHEN NOT EXISTS(SELECT 1 FROM member m JOIN user u ON u.id=m.user_id WHERE m.user_id=NEW.user_id AND m.status='active' AND u.emailVerified=1) BEGIN SELECT RAISE(ABORT,'authority_changed'); END;
CREATE TRIGGER storage_current_member BEFORE INSERT ON storage_reservation WHEN NOT EXISTS(SELECT 1 FROM member m JOIN user u ON u.id=m.user_id WHERE m.user_id=NEW.owner_id AND m.status='active' AND u.emailVerified=1) BEGIN SELECT RAISE(ABORT,'authority_changed'); END;
